bool is_prime(int n) {
    if (n < 2) return false;
    for (int d = 2; d * d <= n; ++d) {
        if (n % d == 0) return false;
    }
    return true;
}

int count_primes_below(int limit) {
    int count = 0;
    for (int n = 2; n < limit; ++n) {
        if (is_prime(n)) ++count;
    }
    return count;
}

