#include <vector>

// v is read-only and possibly large: const& avoids a copy and forbids changes.
// mean and max are outputs, so they must be non-const references.
int count_above(const std::vector<double>& v, double threshold) {
    int n = 0;
    for (const auto& x : v) if (x > threshold) ++n;
    return n;
