1. Copies the whole vector on every call. Use `const std::vector<double>& v`.
2. Won't compile: assigning through a const reference. If the function is meant to reset, take `int& counter`.
3. Returns a reference to a local that dies at `}`: a dangling reference, undefined behaviour (the compiler warns). Return `int` by value.
4. `auto r` copies each element, so the vector is unchanged. Use `for (auto& r : readings) r *= 0.9;`.

```cpp
#include <vector>
#include <cassert>

double average(const std::vector<double>& v) {
    double s = 0;
    for (const auto& x : v) s += x;
    return v.empty() ? 0.0 : s / v.size();
}
void reset(int& counter) { counter = 0; }
int next_id() { int id = 42; return id; }

int main() {
    std::vector<double> readings{10, 20};
    for (auto& r : readings) r *= 0.9;
    assert(readings[0] == 9.0);
    int c = 5; reset(c); assert(c == 0);
    assert(next_id() == 42);
    assert(average({1, 3}) == 2.0);
}
```

```cpp
#include <vector>

constexpr double kEps = 1e-12;

void normalize(std::vector<double>& v) {
    if (v.empty()) return;
    double lo = v[0], hi = v[0];
    for (const auto& x : v) {
        if (x < lo) lo = x;
        if (x > hi) hi = x;
    }
    double range = hi - lo;
    for (auto& x : v) x = (range < kEps) ? 0.0 : (x - lo) / range;
}

int main() { std::vector<double> v{1, 3}; normalize(v); return v[1] == 1.0 ? 0 : 1; }
```

