  int start = (line[2] == '-') ? 3 : 2;
  if (start >= (int)line.length()) return false;
  for (int i = start; i < (int)line.length(); i++) if (!isDigit(line[i])) return false;
  kind = line[0];
  value = line.substring(2).toInt();
  return true;
}

