  arm.attach(SERVO_PIN);
  pinMode(BUTTON, INPUT_PULLUP);
  Serial.begin(115200);
  Serial.println("servo-demo ready: S:<0-180>");
}

void loop() {
  unsigned long now = millis();

  // Mode button (debounced, week 8)
  if (digitalRead(BUTTON) == LOW && now - lastPress > 250) {
    lastPress = now;
    mode = (Mode)((mode + 1) % 3);
    Serial.print("mode "); Serial.println(mode);
  }

  if (mode == POT_MODE) {
    target = map(analogRead(POT), 0, 1023, 0, 180);
  } else if (mode == SERIAL_MODE && Serial.available()) {
    char kind; int value;
    if (parseCommand(Serial.readStringUntil('\n'), kind, value) && kind == 'S') {
      target = constrain(value, 0, 180);
      Serial.print("ok "); Serial.println(target);
    } else {
      Serial.println("err");
    }
  } else if (mode == ROUTINE_MODE && abs(pos - target) < 1) {
    routineIdx = (routineIdx + 1) % ROUTINE_LEN;
    target = routine[routineIdx];
  }

  // Smooth motion: every 15 ms, move a fraction of the remaining distance (ease-out)
  if (now - lastStep >= 15) {
    lastStep = now;
    pos += (target - pos) * 0.1;
    arm.write((int)(pos + 0.5));
    analogWrite(LED, map((int)pos, 0, 180, 0, 255));
  }
}
