bool parse_command(std::string_view line, char& kind, int& value) {
    std::string t = trim(line);
    if (t.size() < 3 || !std::isalpha(static_cast<unsigned char>(t[0])) || t[1] != ':') return false;
    std::size_t i = 2;
    if (t[i] == '-') ++i;
    if (i >= t.size()) return false;
    for (std::size_t j = i; j < t.size(); ++j) {
        if (!std::isdigit(static_cast<unsigned char>(t[j]))) return false;
    }
    kind = t[0];
    value = std::stoi(t.substr(2));
    return true;
}

int main() { char k; int v; return parse_command("S:1", k, v) ? 0 : 1; }
